+
+    .question[aria-expanded="true"] .icon {
+      transform: rotate(45deg);
+      background: var(--accent-strong);
+    }
+
+    .details {
+      padding: 0 1.25rem 1.25rem;
+      color: var(--muted);
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+      padding-top: 0.1rem;
+    }
+
